const PROG ={};
let LOADP = 0;
const loadBar = f =>{
LOADP = Math.max(LOADP,Math.min(1,f));
const b = document.getElementById('goFill');
if(b)b.style.width =(LOADP * 100).toFixed(1)+ '%';
};
window.__loadBar = loadBar;
function prog(){
let a = 0;
for(const k in PROG)a += PROG[k];
loadBar((0.8 * a)/ FILETOTAL);
}
const PRE ={};
const fetchTxt = url =>{
if(!PRE[url])
PRE[url]=(async()=>{
let last = null;
for(let tries = 0;tries < 4;tries++){
try{
const r = await fetch(url,tries ?{cache: 'reload'}: undefined);
if(!r.ok)throw new Error('Could not load ' + url);
const want = +r.headers.get('content-length')|| 0;
const rd = r.body.getReader();
const parts =[];
let got = 0;
for(;;){
const{done,value}= await rd.read();
if(done)break;
parts.push(value);
got += value.length;
PROG[url]= got;
prog();
}
if(want && got < want)throw new Error('cut short');
const txt = new TextDecoder().decode(await new Blob(parts).arrayBuffer());
if(
url.endsWith('.txt')&&
txt.trim().length % 4
)
throw new Error('cut short');
return txt;
}catch(e){
last = e;
PROG[url]= 0;
await new Promise(r => setTimeout(r,400 *(tries + 1)));
}
}
throw last;
})();
return PRE[url];
};
