function vnoise(x,z){
const xi = Math.floor(x),
zi = Math.floor(z),
xf = x - xi,
zf = z - zi,
u = xf * xf *(3 - 2 * xf),
v = zf * zf *(3 - 2 * zf);
const a = hash2(xi,zi),
b = hash2(xi + 1,zi),
c = hash2(xi,zi + 1),
d = hash2(xi + 1,zi + 1);
return a +(b - a)* u +(c - a)* v +(a - b - c + d)* u * v;
}
