const LD_SKIP = new Set([
'frogjump.glb',
'dragonfly.glb',
'tadpole.glb',
'ferns.glb',
'mushrooms.glb',
'bananaleaf.glb',
'riceplant.glb'
]);
async function ld(f){
if(LD_SKIP.has(f))return null;
const name = FILEPATH[f]|| f.replace('.glb','.glb.txt');
const txt = await fetchTxt(name);
const bin = atob(txt.trim());
const u = new Uint8Array(bin.length);
for(let i = 0;i < bin.length;i++)u[i]= bin.charCodeAt(i);
return new Promise((res,rej)=>
loader.parse(
u.buffer,
'',
g =>{
g.scene.traverse(
o =>{
if(o.isMesh){
o.userData.src = f;
if(o.geometry)o.geometry.userData.src = f;
}
}
);
res(g);
},
rej
)
);
}
