function modelParts(gl,keep){
gl.scene.updateMatrixWorld(true);
const out =[];
gl.scene.traverse(o =>{
if(o.isMesh &&(!keep || keep(o))){
out.push({geo: o.geometry.clone().applyMatrix4(o.matrixWorld),mat: o.material,name: o.name});
}
});
return out;
}
function fitParts(parts,size,by = 'y'){
const bb = new THREE.Box3();
for(const p of parts){
p.geo.computeBoundingBox();
bb.union(p.geo.boundingBox);
}
const sz = bb.getSize(new V3());
const k = size /(by === 'y' ? sz.y : by === 'x' ? sz.x : Math.max(sz.x,sz.z));
const c = bb.getCenter(new V3());
for(const p of parts){
p.geo.translate(-c.x,-bb.min.y,-c.z);
p.geo.scale(k,k,k);
p.geo.computeBoundingBox();
}
return parts;
}
function partEach(parts,size){
for(const p of parts){
p.geo.computeBoundingBox();
const bb = p.geo.boundingBox,
sz = bb.getSize(new V3());
const c = bb.getCenter(new V3());
p.geo.translate(-c.x,-bb.min.y,-c.z);
const k = size / sz.y;
p.geo.scale(k,k,k);
p.geo.computeBoundingBox();
}
return parts;
}
