function entryChime(){
if(!AUD.ctx || !AUD.on)return;
const ctx = AUD.ctx,
t0 = ctx.currentTime;
const notes =[523.25,587.33,659.25,783.99,880,1046.5,1174.66,1318.5];
const out = ctx.createGain();
out.gain.value = 0.16 * 0.6 * MUSV();
out.connect(AUD.master ? AUD.bus('chime: arrival'): ctx.destination);
notes.forEach((f,i)=>{
for(const[mul,v]of[
[1,1],
[2,0.25],
[3.01,0.08]
]){
const o = ctx.createOscillator(),
g = ctx.createGain();
o.type = 'sine';
o.frequency.value = f * mul;
const st = t0 + i * 0.13;
g.gain.setValueAtTime(0,st);
g.gain.linearRampToValueAtTime(v * 0.5,st + 0.01);
g.gain.exponentialRampToValueAtTime(0.0005,st + 2.4);
o.connect(g);
g.connect(out);
o.start(st);
o.stop(st + 2.5);
}
});
}
