let noseCool = 8;
function updateButterflies(dt,time){
const night = NIGHTISH();
noseCool -= dt;
if(
!night &&
noseCool < 0 &&
P.mode === 'ground' &&
P.speed < 0.05 &&
(P.idle || 0)> 3 &&
!butterflies.some(b => b.state === 'toNose' || b.state === 'nose')
){
let best = null,
bd = 9;
for(const b of butterflies){
if(b.state !== 'fly')continue;
const d = b.p.distanceTo(P.pos);
if(d < bd){
bd = d;
best = b;
}
}
if(best){
best.state = 'toNose';
best.t = 8;
}
noseCool = 25 + Math.random()* 25;
}
for(const b of butterflies){
b.grp.visible = !night;
if(night)continue;
b.t -= dt;
if(b.state === 'toNose' || b.state === 'nose'){
const hp = headPoint();
hp.y += 0.07;
if(P.speed > 0.12 || P.mode !== 'ground' || b.t < 0){
b.state = 'fly';
b.t = 3;
b.v.set(0,1.4,0);
}else if(b.state === 'toNose'){
const d = hp.clone().sub(b.p);
const L2 = d.length();
if(L2 < 0.03){
b.state = 'nose';
b.t = 4 + Math.random()* 3;
b.p.copy(hp);
}else{
b.v.lerp(
d
.normalize()
.multiplyScalar(Math.min(1.2,L2 * 2 + 0.25))
.add(new V3(0,Math.sin(time * 9 + b.ph)* 0.25,0)),
1 - Math.exp(-4 * dt)
);
b.p.addScaledVector(b.v,dt);
b.yaw = Math.atan2(b.v.x,b.v.z);
}
b.flap = 0.15 + 0.95 * Math.abs(Math.sin(time * 16 + b.ph));
}else{
b.p.copy(hp);
b.flap = Math.max(0,Math.sin(time * 1.4 + b.ph))* 0.9;
b.yaw = P.yaw;
}
b.R.rotation.z = b.flap;
b.L.rotation.z = -b.flap;
b.grp.position.copy(b.p);
b.grp.rotation.set(0,b.yaw,0);
continue;
}
if(b.home.distanceTo(P.pos)> 26){
const a = Math.random()* 6.283,
r = 4 + Math.random()* 14;
b.home.set(P.pos.x + Math.cos(a)* r,0,P.pos.z + Math.sin(a)* r);
if(b.p.distanceTo(P.pos)> 30){
b.p.copy(b.home);
b.p.y = heightAt(b.p.x,b.p.z)+ 1.2;
}
}
const gy = heightAt(b.p.x,b.p.z);
const dc = Math.min(b.p.distanceTo(P.pos),comp.P ? b.p.distanceTo(comp.P.pos): 1e9);
if(b.state === 'rest'){
b.flap = Math.max(0,Math.sin(time * 1.5 + b.ph))* 0.9;
if(b.t < 0 || dc < 1.1){
b.state = 'fly';
b.t = 3 + Math.random()* 6;
b.v.y = 1.2;
}
}else{
const wob = new V3(
Math.sin(time * 2.3 + b.ph * 3)* 0.9,
Math.sin(time * 3.7 + b.ph)* 0.7,
Math.cos(time * 1.9 + b.ph * 2)* 0.9
);
const want = b.home.clone().sub(b.p).setY(0).multiplyScalar(0.25).add(wob);
const hgt = b.p.y - gy;
want.y +=(0.7 + 0.5 * Math.sin(time * 0.7 + b.ph)- hgt)* 1.2;
if(dc < 1.6){
const away = b.p.clone().sub(P.pos).normalize().multiplyScalar(2.5);
away.y = 1.6;
want.add(away);
}
b.v.lerp(want,1 - Math.exp(-2.2 * dt));
b.p.addScaledVector(b.v,dt);
if(b.p.y < gy + 0.08)b.p.y = gy + 0.08;
b.flap = 0.15 + 0.95 * Math.abs(Math.sin(time * 16 + b.ph));
if(b.t < 0 && dc > 2.5 && hgt < 0.9){
b.state = 'rest';
b.t = 2 + Math.random()* 5;
b.p.y = gy + 0.12 + Math.random()* 0.15;
}
}
b.R.rotation.z = b.flap;
b.L.rotation.z = -b.flap;
if(b.v.lengthSq()> 0.01 && b.state !== 'rest')
b.yaw = Math.atan2(b.v.x,b.v.z);
b.grp.position.copy(b.p);
b.grp.rotation.set(b.state === 'rest' ? 0 : -0.25,b.yaw,0);
}
}
function updateTadpoles(dt,time){
for(const t of tadpoles){
t.t -= dt;
const dc = Math.hypot(t.x - P.pos.x,t.z - P.pos.z);
let want = 0.12;
if(dc < 1.3){
const a = Math.atan2(t.x - P.pos.x,t.z - P.pos.z);
t.tx = t.x + Math.sin(a)* 1.5;
t.tz = t.z + Math.cos(a)* 1.5;
want = 0.9;
}else if(t.t <= 0 || Math.hypot(t.tx - t.x,t.tz - t.z)< 0.08){
t.t = 2 + Math.random()* 4;
const a = Math.random()* 6.28,
r = 0.3 + Math.random()* 1.2;
t.tx = t.x + Math.sin(a)* r;
t.tz = t.z + Math.cos(a)* r;
want = Math.random()< 0.4 ? 0 : 0.12;
}
if(waterLevelAt(t.tx,t.tz)< -1e8 || waterLevelAt(t.tx,t.tz)- heightAt(t.tx,t.tz)< 0.08){
t.tx = t.x;
t.tz = t.z;
want = 0;
}
t.spd = damp(t.spd,want,4,dt);
const dy = Math.atan2(t.tx - t.x,t.tz - t.z);
t.yaw += angDiff(t.yaw,dy)* Math.min(1,dt * 5);
t.x += Math.sin(t.yaw)* t.spd * dt;
t.z += Math.cos(t.yaw)* t.spd * dt;
t.ph += dt *(4 + t.spd * 30);
t.g.position.set(t.x,t.y + Math.sin(time * 1.3 + t.ph * 0.1)* 0.01,t.z);
t.g.rotation.y = t.yaw + Math.sin(t.ph)*(0.18 + t.spd * 0.5);
}
}
