function kit(scene3,groupOf){
const groups = new Map();
scene3.updateMatrixWorld(true);
scene3.traverse(o =>{
if(!o.isMesh)return;
const k = groupOf(o);
if(!groups.has(k))groups.set(k,[]);
groups.get(k).push(o);
});
return[...groups.values()].map(meshes =>{
const box = new THREE.Box3();
meshes.forEach(m => box.expandByObject(m));
const c = box.getCenter(new V3());
const parts = meshes.map(m =>{
const g = floatAttrs(m.geometry.clone());
g.applyMatrix4(m.matrixWorld);
g.translate(-c.x,-box.min.y,-c.z);
if(!g.attributes.normal)g.computeVertexNormals();
const mat = m.material.clone();
if(mat.transparent){
mat.transparent = false;
mat.depthWrite = true;
mat.alphaTest = 0.42;
}
mat.side = THREE.DoubleSide;
return{g,mat};
});
return{parts,h: box.max.y - box.min.y,verts: parts.reduce((a,p)=> a + p.g.attributes.position.count,0)};
});
}
