catRoot.add(vis);
const mixer = new THREE.AnimationMixer(root);
const groom = mixer.clipAction(groomClip);
groom.play();
return{
kind,
root,
bones,
rest,
holder,
vis,
catRoot,
mixer,
groom,
scale: sc,
hindLift,
body,
shells: shellGroup,
allBones: Object.values(bones)
};
