function refSample(arr,t){
const n = arr.length,
x =(((t % 1)+ 1)% 1)* n,
i = Math.floor(x),
f = x - i,
a = arr[i % n],
b = arr[(i + 1)% n];
return Array.isArray(a)? a.map((v,k)=> v +(b[k]- v)* f): a +(b - a)* f;
}
function refFoot(r,id,lp,S,H){
const[zn,yn,fold]= refSample(r.legs[id],lp);
return[zn * S,yn * H,yn,fold];
}
function gaitFoot(p,D,S,H){
if(p < D){
const s = p / D;
return[S * 0.5 - S * s,0,0,s > 0.85 ?((s - 0.85)/ 0.15)* 0.35 : 0];
}
const s =(p - D)/(1 - D);
const e = s * s *(3 - 2 * s);
return[
-S * 0.5 + S * e,
H * Math.pow(Math.sin(Math.PI * s),0.8),
Math.sin(Math.PI * s),
Math.sin(Math.PI * Math.min(1,s / 0.55))*(s < 0.55 ? 1 : 0)
];
}
function rot2(x,y,a){
const c = Math.cos(a),
s = Math.sin(a);
return[x * c - y * s,x * s + y * c];
}
function setupRig(cat){
const B = cat.bones;
const R = b => cat.rest.get(B[b]).mp;
const legDef =[
['LF',1,'j_l_humerous','j_l_elbow','j_l_wrist','j_l_palm','j_l_finger'],
['RF',1,'j_r_humerous','j_r_elbow','j_r_wrist','j_r_palm','j_r_finger'],
['LH',0,'j_l_femur','j_l_knee','j_l_ankle','j_l_ball','j_l_toe'],
['RH',0,'j_r_femur','j_r_knee','j_r_ankle','j_r_ball','j_r_toe']
];
cat.legs = legDef.map(([id,front,...bn])=>{
const p = bn.map(R);
return{
id,
front: !!front,
b: bn.map(n => B[n]),
L1: p[0].distanceTo(p[1]),
L2: p[1].distanceTo(p[2]),
foot: p[3].clone(),
fv:[p[2].x - p[3].x,p[2].y - p[3].y],
tv:[p[4].x - p[3].x,p[4].y - p[3].y],
pole: new V3(front ? -1 : 1,0,0),
side: Math.sign(p[3].z)
};
});
cat.lhSide = cat.legs.find(l => l.id === 'LH').side;
if(cat.hindLift){
const lh = cat.legs.find(l => l.id === 'LH'),
lf = cat.legs.find(l => l.id === 'LF');
for(const l of cat.legs)if(!l.front)l.foot.y += cat.hindLift;
cat.hindPitch = Math.atan2(cat.hindLift * 0.85,Math.abs(lf.foot.x - lh.foot.x)|| 1);
}
cat.tail =[1,2,3,4,5,6].map(i => B['j_tail_' + i]);
cat.cache ={
q: cat.allBones.map(b => b.quaternion.clone()),
p: cat.allBones.map(b => b.position.clone()),
s: cat.allBones.map(b => b.scale.clone())
};
cat.tailLag = new Array(6).fill(0);
cat.lookYaw = 0;
cat.lookPitch = 0;
}
