function bakeStatic(root){
root.updateMatrixWorld(true);
const byMat = new Map();
const v = new V3();
root.traverse(o =>{
if(!o.isMesh)return;
const g = o.geometry,
P0 = g.attributes.position,
n = P0.count;
const pos = new Float32Array(n * 3);
for(let i = 0;i < n;i++){
if(o.isSkinnedMesh)o.getVertexPosition(i,v);
else v.fromBufferAttribute(P0,i);
v.applyMatrix4(o.matrixWorld);
pos[i * 3]= v.x;
pos[i * 3 + 1]= v.y;
pos[i * 3 + 2]= v.z;
}
const ng = new THREE.BufferGeometry();
ng.setAttribute('position',new THREE.BufferAttribute(pos,3));
const uv = g.attributes.uv;
if(uv){
const a = new Float32Array(n * 2);
for(let i = 0;i < n;i++){
a[i * 2]= uv.getX(i);
a[i * 2 + 1]= uv.getY(i);
}
ng.setAttribute('uv',new THREE.BufferAttribute(a,2));
}
if(g.index)ng.setIndex(Array.from(g.index.array));
ng.computeVertexNormals();
const k = o.material;
if(!byMat.has(k))byMat.set(k,[]);
byMat.get(k).push(ng);
});
const grp = new THREE.Group();
for(const[m,gs]of byMat){
const mm = m.clone();
mm.side = THREE.DoubleSide;
if(mm.alphaTest === 0 && mm.transparent){
mm.alphaTest = 0.4;
mm.transparent = false;
}
celMat(mm,'wpk',0.8);
const me = new THREE.Mesh(mergeGeometries(gs.map(x =>(x.index ? x : x))),mm);
me.castShadow = true;
grp.add(me);
}
const b = new THREE.Box3().setFromObject(grp);
return{grp,box: b};
}
