function nbEyeTex(srcTex,mode){
const img = srcTex.image;
const W = img.width,
H = img.height;
const[c,x]= cnv(W,H);
x.drawImage(img,0,0);
const cx = 0.862 * W,
cy = 0.074 * H,
R = 0.08 * W;
const iris = mode === 'honey' ? '#ffbf2e' : '#8fe6ff',
shade = mode === 'honey' ? '#e08a12' : '#4fb7ec',
line = mode === 'honey' ? '#4a2a06' : '#123a58';
x.save();
x.translate(cx,cy);
x.scale(1,(H / W)* 0.5);
x.translate(-cx,-cy);
x.fillStyle = '#fbf8f2';
x.beginPath();
x.arc(cx,cy,R * 1.25,0,7);
x.fill();
x.fillStyle = line;
x.beginPath();
x.arc(cx,cy,R * 1.0,0,7);
x.fill();
x.fillStyle = iris;
x.beginPath();
x.arc(cx,cy,R * 0.9,0,7);
x.fill();
x.fillStyle = shade;
x.beginPath();
x.ellipse(cx,cy - R * 0.62,R * 0.9,R * 0.4,0,0,7);
x.fill();
x.fillStyle = '#070605';
x.beginPath();
x.ellipse(cx,cy,R * 0.42,R * 0.5,0,0,7);
x.fill();
x.fillStyle = '#fff';
x.beginPath();
x.arc(cx - R * 0.3,cy - R * 0.32,R * 0.2,0,7);
x.fill();
x.restore();
const t = new THREE.CanvasTexture(c);
t.flipY = srcTex.flipY;
t.colorSpace = THREE.SRGBColorSpace;
return t;
}
