const qo = new Q(),
qn = new Q();
for(let[o,n]of NB_MAP){
if(flip)n = n.replace('-L-','-X-').replace('-R-','-L-').replace('-X-','-R-');
const ob = cat.bones[o],
bn = nb.B[n];
if(!ob || !bn)continue;
ob.getWorldQuaternion(qo);
bn.getWorldQuaternion(qn);
nb.pairs.push({ob,bn,d: qo.clone().invert().multiply(qn)});
}
const op = cat.bones.j_body.getWorldPosition(new V3()),
np = nb.B['cat_bip-Pelvis'].getWorldPosition(new V3());
cat.vis.worldToLocal(op);
cat.vis.worldToLocal(np);
nb.pelOff = np.sub(op);
