function aimSign(sg){
const g = sg.grp;
g.updateMatrixWorld(true);
const c = g.getWorldPosition(new V3());
const L = signPlaces()
.map(p =>({...p,d: Math.hypot(p.x - c.x,p.z - c.z),a: Math.atan2(p.z - c.z,p.x - c.x)}))
.filter(p => p.d > 4)
.sort((a,b)=> a.d - b.d);
if(!L.length)return;
const A = L.find(p => p.k === sg.key)|| L[0];
L.splice(L.indexOf(A),1);
const diff =(u,w)=> Math.abs(((u - w + Math.PI * 3)%(Math.PI * 2))- Math.PI);
let B = L.find(p => diff(p.a,A.a)> 1.05)|| L.find(p => diff(p.a,A.a)> 0.6)|| null;
sg.A = A;
sg.B = B;
const q = new THREE.Quaternion();
g.getWorldQuaternion(q);
const gy = new THREE.Euler().setFromQuaternion(q,'YXZ').y;
const s = g.getWorldScale(new V3());
const turn =
(p,flip)=>{
const dx = p.x - c.x,
dz = p.z - c.z;
return(flip ? Math.atan2(dz,-dx): Math.atan2(-dz,dx))- gy;
};
sg.top.rotation.y = turn(A,false);
if(B)sg.low.rotation.y = turn(B,true);
else sg.low.rotation.y = sg.top.rotation.y + Math.PI;
boardWord(sg.top,A.w);
boardWord(sg.low,B ? B.w : '');
}
function boardWord(m,w){
if(m.userData.word === w)return;
m.userData.word = w;
for(const c of[...m.children])m.remove(c);
if(!w)return;
const g = m.geometry;
g.computeBoundingBox();
const b = g.boundingBox;
const pa = g.attributes.position;
const NB = 14,
x0 = b.min.x,
x1 = b.max.x,
L = x1 - x0;
const lo = new Array(NB).fill(1e9),
hi = new Array(NB).fill(-1e9);
for(let i = 0;i < pa.count;i++){
const k = Math.min(NB - 1,Math.floor(((pa.getX(i)- x0)/ L)* NB));
const y = pa.getY(i);
if(y < lo[k])lo[k]= y;
if(y > hi[k])hi[k]= y;
}
const hgt = lo.map((l,k)=> hi[k]- l);
const mh = Math.max(...hgt.filter(h => h > 0));
const body =[];
for(let k = 0;k < NB;k++)if(hgt[k]> mh * 0.72)body.push(k);
if(!body.length)return;
let sx = 0,
sy = 0,
sxx = 0,
sxy = 0;
for(const k of body){
const x = x0 +((k + 0.5)/ NB)* L,
y =(lo[k]+ hi[k])/ 2;
sx += x;
sy += y;
sxx += x * x;
sxy += x * y;
}
const n = body.length;
const den = n * sxx - sx * sx;
const slope = den ?(n * sxy - sx * sy)/ den : 0;
const bx0 = x0 +(body[0]/ NB)* L,
bx1 = x0 +((body[body.length - 1]+ 1)/ NB)* L;
const bl = bx1 - bx0;
const minH = Math.min(...body.map(k => hgt[k]));
const cx =(bx0 + bx1)/ 2,
cy =(sy - slope * sx)/ n + slope * cx;
const ang = Math.atan(slope);
const pw =(bl * 0.86)/ Math.cos(ang),
ph = minH * 0.62;
const CW = 512,
CH = Math.max(64,Math.round((CW * ph)/ pw));
const[cv,x]= cnv(CW,CH);
x.clearRect(0,0,CW,CH);
x.fillStyle = 'rgba(248,240,218,.95)';
let fs = Math.round(CH * 0.86);
x.font = '700 ' + fs + 'px Fraunces, Georgia, serif';
x.textAlign = 'center';
x.textBaseline = 'middle';
while(x.measureText(w).width > CW * 0.94 && fs > 12){
fs -= 2;
x.font = '700 ' + fs + 'px Fraunces, Georgia, serif';
}
x.fillText(w,CW / 2,CH * 0.54);
const t = new THREE.CanvasTexture(cv);
t.colorSpace = THREE.SRGBColorSpace;
t.anisotropy = 4;
const mat = new THREE.MeshStandardMaterial({
map: t,
emissiveMap: t,
emissive: 0x8a8270,
emissiveIntensity: 0.35,
transparent: true,
roughness: 0.9,
depthWrite: false,
polygonOffset: true,
polygonOffsetFactor: -2
});
for(const side of[1,-1]){
const pl = new THREE.Mesh(new THREE.PlaneGeometry(pw,ph),mat);
pl.position.set(cx,cy,side > 0 ? b.max.z + 0.005 : b.min.z - 0.005);
if(side < 0)pl.rotation.set(0,Math.PI,-ang);
else pl.rotation.z = ang;
pl.renderOrder = 2;
m.add(pl);
}
}
