function trimBuf(b){
try{
const d = b.getChannelData(0),
sr = b.sampleRate,
w = Math.round(sr * 0.01);
let a = -1,
z = -1;
for(let i = 0;i + w <= d.length;i += w){
let e = 0;
for(let j = i;j < i + w;j++)e += d[j]* d[j];
const r = Math.sqrt(e / w);
if(r > 0.02){
if(a < 0)a = i;
z = i + w;
}
}
if(a < 0)return b;
a = Math.max(0,a - Math.round(sr * 0.015));
z = Math.min(d.length,z + Math.round(sr * 0.12));
const o = AUD.ctx.createBuffer(b.numberOfChannels,z - a,sr);
for(let c = 0;c < b.numberOfChannels;c++)o.getChannelData(c).set(b.getChannelData(c).subarray(a,z));
return o;
}catch(e){
return b;
}
}
