function fireRoarBuf(){
if(!AUD.ctx || AUD.buf.furnace_roar)return;
const sr = AUD.ctx.sampleRate,
N = Math.floor(sr * 2),
b = AUD.ctx.createBuffer(1,N,sr),
d = b.getChannelData(0);
let y1 = 0,
y2 = 0,
y3 = 0,
pk = 0,
cr = 0,
cv = 0;
for(let i = 0;i < N;i++){
const t = i / sr;
const env = t < 0.09 ? Math.pow(t / 0.09,1.6): Math.exp(-(t - 0.09)* 1.9);
const a = 0.012 + 0.22 * Math.exp(-t * 2.6)*(t < 0.09 ? t / 0.09 : 1);
const x = Math.random()* 2 - 1;
y1 += a *(x - y1);
y2 += 0.02 *(y1 - y2);
y3 += 0.004 *(x - y3);
if(cr <= 0 && t < 1.4 && Math.random()< 0.0007 *(1.4 - t)){
cr = Math.floor(sr *(0.002 + Math.random()* 0.005));
cv =(Math.random()* 0.6 + 0.4)*(Math.random()< 0.5 ? -1 : 1);
}
let c = 0;
if(cr > 0){
c = cv *(Math.random()* 0.6 + 0.4);
cr--;
}
const v =(y1 * 2.4 + y2 * 6 + y3 * 14)* env + c * 0.5 * Math.exp(-t * 1.2);
d[i]= v;
pk = Math.max(pk,Math.abs(v));
}
const k = 0.9 / Math.max(pk,1e-4);
for(let i = 0;i < N;i++)d[i]*= k;
AUD.buf.furnace_roar = b;
}
