const DRES =(()=>{
const MAX = renderer.getPixelRatio(),
MIN0 = Math.min(MAX,1.2),
MIN1 = Math.min(MAX,0.8);
let MIN = MIN0,
slow = 0;
let r = MAX,
ceil = MAX,
acc = 0,
n = 0,
t0 = 0,
lastF = 0,
good = 0,
ceilT = 0;
const apply = v =>{
r = Math.round(v * 100)/ 100;
renderer.setPixelRatio(r);
renderer.setSize(innerWidth,innerHeight);
if(composer){
composer.setPixelRatio(r);
composer.setSize(innerWidth,innerHeight);
}
if(PAINT)PAINT.uniforms.uRes.value.set(innerWidth * r,innerHeight * r);
};
return now =>{
if(lastF){
const d = now - lastF;
if(d < 250){
acc += d;
n++;
}
}
lastF = now;
if(!t0)t0 = now;
if(now - t0 < 2000 || n < 20)return;
const avg = acc / n;
acc = 0;
n = 0;
t0 = now;
if(window.__JACK && window.__JACK.showing)return;
if(ceil < MAX && now - ceilT > 20000)ceil = MAX;
slow =
avg > 34 ? slow + 1 : 0;
MIN = slow >= 2 ? MIN1 : avg < 24 ? MIN0 : MIN;
if(avg > 24 && r > MIN){
ceil = Math.max(MIN,r - 0.05);
ceilT = now;
good = 0;
apply(Math.max(MIN,r - 0.15));
}else if(avg < 18 && r < ceil){
if(++good >= 2){
good = 0;
apply(Math.min(ceil,r + 0.1));
}
}else good = 0;
};
})();
