function ancLeafMat(
base,
o,
gy
){
const m = base.clone();
const prev = base.onBeforeCompile;
const invS = 1 / Math.max(1e-4,o.scale.x);
m.onBeforeCompile =(sh,r)=>{
if(prev && prev !== THREE.Material.prototype.onBeforeCompile)prev(sh,r);
sh.uniforms.uAncS ={value: invS};
sh.uniforms.uAncY ={value: gy + 4};
if(!sh.uniforms.uTime)sh.uniforms.uTime = grassU.uTime;
if(!sh.uniforms.uWind)sh.uniforms.uWind = grassU.uWind;
if(!sh.uniforms.uWPh)sh.uniforms.uWPh = grassU.uWPh;
if(!sh.uniforms.uGust)sh.uniforms.uGust = grassU.uGust;
const decl = /uniform float uTime/.test(sh.vertexShader)
? ''
: 'uniform float uTime,uWind,uWPh,uGust;';
sh.vertexShader = sh.vertexShader
.replace('#include <common>','#include <common>\nuniform float uAncS,uAncY;' + decl)
.replace(
'#include <begin_vertex>',
'#include <begin_vertex>\n#ifndef USE_INSTANCING\n{vec4 aw=modelMatrix*vec4(transformed,1.);float kh=clamp((aw.y-uAncY)/12.,0.,1.4);float ph=aw.x*.13+aw.z*.11;vec3 sw=vec3(sin((uTime*1.1+uWPh*.6)+ph),.0,cos((uTime*.9+uWPh*.5)+ph*1.3))*(.03+.11*uWind)*kh+vec3(sin(uTime*2.7+ph*3.1),sin(uTime*2.3+ph*2.)*.4,cos(uTime*2.9+ph*2.7))*.012*kh*(.4+uWind);/* Build 258: sway sized in world metres, whatever the scale of the model */transformed+=(inverse(mat3(modelMatrix))*sw);}\n#endif'
);
};
m.customProgramCacheKey =()=>
'ancLeaf' +(base.customProgramCacheKey ? base.customProgramCacheKey(): '');
return m;
}
function levQ(
i,
t
){
return new THREE.Quaternion().setFromEuler(
new THREE.Euler(Math.sin(t * 1.9 + i * 1.7)* 0.22,0,Math.sin(t * 1.3 + i)* 0.12)
);
}
window.__levTip =(...a)=> levTip(...a);
function levTip(L,t,toSpace){
const q = L.m.userData.base.clone().multiply(levQ(L.i,t));
const p = L.m.position
.clone()
.add(new THREE.Vector3(0,L.h * 0.92,0).multiply(L.m.scale).applyQuaternion(q));
L.m.parent.updateMatrixWorld();
p.applyMatrix4(L.m.parent.matrixWorld);
return toSpace.worldToLocal(p);
}
