const tinyChime =()=>{
if(!AUD.ctx || !AUD.on)return;
const ctx = AUD.ctx,
t0 = ctx.currentTime;
const out = ctx.createGain();
out.gain.value = 0.08;
out.connect(AUD.master ? AUD.bus('chime: puff'): ctx.destination);
[1318.5,1567.98,2093].forEach((f,i)=>{
const o = ctx.createOscillator(),
gg = ctx.createGain();
o.frequency.value = f;
gg.gain.setValueAtTime(0,t0 + i * 0.09);
gg.gain.linearRampToValueAtTime(0.5,t0 + i * 0.09 + 0.01);
gg.gain.exponentialRampToValueAtTime(0.0005,t0 + i * 0.09 + 1.4);
o.connect(gg);
gg.connect(out);
o.start(t0 + i * 0.09);
o.stop(t0 + i * 0.09 + 1.5);
});
};
