I.findMoon =()=>{
const rc = new THREE.Raycaster();
rc.far = 140;
const objs =[];
scene.traverse(o =>{
if(
(o.isMesh || o.isInstancedMesh)&&
o.visible &&
!o.userData.noRay &&
!(o.material && o.material.uniforms && o.material.uniforms.uGust)&&
!(o.isInstancedMesh && o.count > 3000)
){
if(!o.geometry.boundingSphere)o.geometry.computeBoundingSphere();
if(o.geometry.boundingSphere.radius < 300)objs.push(o);
}
});
const from = C_win,
base = new V3().subVectors(L_win,C_win).setY(0).normalize();
const yaw0 = Math.atan2(base.x,base.z);
let best = null,
bs = -1e9;
for(let a = -0.5;a <= 0.5;a += 0.06)
for(let e = 0.12;e <= 0.5;e += 0.04){
const d = new V3(Math.sin(yaw0 + a)* Math.cos(e),Math.sin(e),Math.cos(yaw0 + a)* Math.cos(e));
rc.set(from,d);
if(rc.intersectObjects(objs,false).length)continue;
let open = 0;
for(const[da,de]of[
[0.05,0],
[-0.05,0],
[0,0.05],
[0,-0.05]
]){
const d2 = new V3(
Math.sin(yaw0 + a + da)* Math.cos(e + de),
Math.sin(e + de),
Math.cos(yaw0 + a + da)* Math.cos(e + de)
);
rc.set(from,d2);
if(!rc.intersectObjects(objs,false).length)open++;
}
const sc = open * 2 - Math.abs(a)* 3 - Math.abs(e - 0.26)* 4;
if(sc > bs){
bs = sc;
best = d;
}
}
window.__moonPick = best ? best.toArray(): null;
if(best && window.__MORE)window.__MORE.moonDir.copy(best);
return best;
};
