const lucaStep = dt =>{
const L = comp.P;
if(!L)return;
if(I.lhop){
const H = I.lhop;
H.t += dt;
const k = Math.min(1,H.t / 0.55);
L.pos.lerpVectors(H.a,H.b,k);
L.pos.y += Math.sin(k * Math.PI)* 0.18;
L.visY = L.pos.y;
L.speed = 0;
if(k >= 1){
I.lhop = null;
L.pos.copy(H.b);
L.visY = L.pos.y;
}
return;
}
const tr = I.trail,
last = tr[tr.length - 1];
if(
P.mode === 'ground' &&
Math.hypot(P.pos.x - last.x,P.pos.z - last.z)> 0.08 &&
Math.abs(P.pos.y - last.y)< 0.2
)
tr.push(P.pos.clone());
if(!I.lfollow || L.script)return;
let lagLeft = 0;
for(let i = tr.length - 1;i > 0 && i > I.ls;i--)lagLeft += tr[i].distanceTo(tr[i - 1]);
let v = 0;
if(I.ls < tr.length - 1 && lagLeft > 0.8){
const q = tr[I.ls + 1];
const dx = q.x - L.pos.x,
dz = q.z - L.pos.z,
d = Math.hypot(dx,dz);
v = T.walk *(lagLeft > 1.6 ? 1.25 : 1);
if(d < v * dt + 0.02){
L.pos.copy(q);
I.ls++;
}else{
L.pos.x +=(dx / d)* v * dt;
L.pos.z +=(dz / d)* v * dt;
L.pos.y = lerp(L.pos.y,q.y,0.3);
const want = Math.atan2(dx,dz);
const dy = angDiff(L.yaw,want);
L.yaw += clamp(dy,-5 * dt,5 * dt);
L.turnRate =(dy / Math.max(dt,1e-3))* 0.2;
}
}else{
const want = Math.atan2(P.pos.x - L.pos.x,P.pos.z - L.pos.z);
L.yaw += clamp(angDiff(L.yaw,want),-3 * dt,3 * dt);
}
L.speed = damp(L.speed || 0,v,6,dt);
L.mode = 'ground';
L.visY = L.pos.y;
L.idle = v > 0 ? 0 :(L.idle || 0)+ dt;
L.lastMove = v > 0 ? 'Walk' : 'Stand';
};
const outYaw = Math.PI;
