const candyCorn =()=>{
const g = new THREE.Group();
const cs =[
[-0.46,0.04],
[0.46,0.04],
[0,0.86]
];
const sh = new THREE.Shape();
const l2 =(a,b,t)=>[a[0]+(b[0]- a[0])* t,a[1]+(b[1]- a[1])* t];
for(let i = 0;i < 3;i++){
const c = cs[i],
p = cs[(i + 2)% 3],
n = cs[(i + 1)% 3];
const a = l2(c,p,0.26),
b = l2(c,n,0.26);
if(i === 0)sh.moveTo(a[0],a[1]);
else sh.lineTo(a[0],a[1]);
sh.quadraticCurveTo(c[0],c[1],b[0],b[1]);
}
sh.closePath();
const geo = new THREE.ExtrudeGeometry(sh,{
depth: 0.16,
bevelEnabled: true,
bevelThickness: 0.15,
bevelSize: 0.1,
bevelSegments: 5,
curveSegments: 10
});
geo.translate(0,0,-0.08);
{
const pa = geo.attributes.position;
for(let i = 0;i < pa.count;i++){
const x = pa.getX(i),
y = pa.getY(i),
z = pa.getZ(i);
const k = Math.max(0,1 - Math.pow(x / 0.55,2))* Math.max(0,1 - Math.pow((y - 0.38)/ 0.6,2));
pa.setZ(i,z *(1 + 0.55 * k));
}
geo.computeVertexNormals();
}
{
const pa = geo.attributes.position,
col = new Float32Array(pa.count * 3);
const Y = new THREE.Color(0xf5b324),
O = new THREE.Color(0xef6d1c),
W = new THREE.Color(0xf6f1e6),
c = new THREE.Color();
for(let i = 0;i < pa.count;i++){
const t =(pa.getY(i)+ 0.1)/ 1.06;
c.copy(t > 0.64 ? W : t > 0.31 ? O : Y);
col.set([c.r,c.g,c.b],i * 3);
}
geo.setAttribute('color',new THREE.BufferAttribute(col,3));
}
const body = new THREE.Mesh(
geo,
new THREE.MeshStandardMaterial({vertexColors: true,roughness: 0.95,metalness: 0})
);
body.castShadow = true;
g.add(body);
const blk = new THREE.MeshStandardMaterial({color: 0x111111,roughness: 0.4}),
wht = new THREE.MeshBasicMaterial({color: 0xffffff});
const fz = 0.27;
for(const sx of[-1,1]){
const e = new THREE.Mesh(new THREE.SphereGeometry(0.05,12,8),blk);
e.scale.set(1,1.1,0.45);
e.position.set(sx * 0.14,0.44,fz);
g.add(e);
const hl = new THREE.Mesh(new THREE.SphereGeometry(0.014,8,6),wht);
hl.position.set(sx * 0.14 - 0.016,0.462,fz + 0.022);
g.add(hl);
}
const sm = new THREE.Mesh(new THREE.TorusGeometry(0.1,0.011,6,20,Math.PI),blk);
sm.rotation.z = Math.PI;
sm.position.set(0,0.33,fz - 0.004);
g.add(sm);
for(const sx of[-1,1]){
const fg = new THREE.Mesh(new THREE.ConeGeometry(0.014,0.034,6),wht);
fg.rotation.z = Math.PI;
fg.position.set(sx * 0.085,0.305,fz + 0.004);
g.add(fg);
}
return g;
};
