const makeKick =(GM,GL)=>{
const M4 = new THREE.Matrix4();
const KK ={
act: new Map(),
grid: null,
v: new V3(),
q: new THREE.Quaternion(),
e: new THREE.Euler(),
s: new V3()
};
const kickTick = dt =>{
if(!KK.grid){
KK.grid = new Map();
GL.forEach((b,i)=>{
const k = Math.floor(b[0]/ 2)+ ',' + Math.floor(b[2]/ 2);
let a = KK.grid.get(k);
if(!a){
a =[];
KK.grid.set(k,a);
}
a.push(i);
});
}
const movers =[P];
try{
if(comp && comp.P)movers.push(comp.P);
}catch(e){}
for(const M of movers){
const sp = M.speed || 0;
if(sp < 1.1 || M.mode !== 'ground')continue;
const R = 0.5 + sp * 0.07,
cx = Math.floor(M.pos.x / 2),
cz = Math.floor(M.pos.z / 2);
const fx = Math.sin(M.yaw || 0),
fz = Math.cos(M.yaw || 0);
for(let ix = cx - 1;ix <= cx + 1;ix++)
for(let iz = cz - 1;iz <= cz + 1;iz++){
const a = KK.grid.get(ix + ',' + iz);
if(!a)continue;
for(const i of a){
if(KK.act.has(i))continue;
const b = GL[i];
const dx = b[0]- M.pos.x,
dz = b[2]- M.pos.z,
d = Math.hypot(dx,dz);
if(d > R || Math.abs(b[1]- M.pos.y)> 0.5)continue;
const nx = d > 1e-3 ? dx / d : fx,
nz = d > 1e-3 ? dz / d : fz,
j =(Math.random()- 0.5)* 0.8,
out = 0.5 + sp * 0.22;
AUD.kickSnd && AUD.kickSnd(M,'petal');
KK.act.set(i,{
p: new V3(b[0],b[1]+ 0.03,b[2]),
v: new V3(
(nx + fx * 0.5)* out + j * 0.5,
1.1 + sp * 0.32 + Math.random()* 0.9,
(nz + fz * 0.5)* out - j * 0.5
),
ph: Math.random()* 6.28,
w: 1.6 + Math.random()* 2
});
}
}
}
if(!KK.act.size)return;
const wd = grassU.uWDir.value;
for(const[i,L]of KK.act){
const b = GL[i];
L.ph += dt * L.w *(L.v.y > 0 ? 2.2 : 1.4);
L.v.y -= 2.4 * dt;
if(L.v.y < -0.55)L.v.y = -0.55;
const dr = 1 - Math.min(1,dt * 1.5);
L.v.x *= dr;
L.v.z *= dr;
L.p.x +=(L.v.x + Math.sin(L.ph)* 0.35 + wd.x * 0.25)* dt;
L.p.z +=(L.v.z + Math.cos(L.ph * 0.8)* 0.35 + wd.y * 0.25)* dt;
L.p.y += L.v.y * dt;
const gy = heightAt(L.p.x,L.p.z)+ 0.012;
if(L.p.y <= gy && L.v.y < 0){
b[0]= L.p.x;
b[1]= gy;
b[2]= L.p.z;
b[3]= L.ph;
KK.e.set(-Math.PI / 2 + Math.sin(L.ph)* 0.25,0,b[3]);
KK.q.setFromEuler(KK.e);
M4.compose(L.p.set(b[0],b[1],b[2]),KK.q,KK.s.setScalar(b[4]));
GM.setMatrixAt(i,M4);
KK.act.delete(i);
for(const[k,a]of KK.grid){
const n = a.indexOf(i);
if(n >= 0){
a.splice(n,1);
break;
}
}
{
const k = Math.floor(b[0]/ 2)+ ',' + Math.floor(b[2]/ 2);
let a = KK.grid.get(k);
if(!a){
a =[];
KK.grid.set(k,a);
}
a.push(i);
}
continue;
}
KK.e.set(L.ph * 1.3,L.ph,L.ph * 0.7);
KK.q.setFromEuler(KK.e);
M4.compose(L.p,KK.q,KK.s.setScalar(b[4]));
GM.setMatrixAt(i,M4);
}
GM.instanceMatrix.needsUpdate = true;
};
return kickTick;
};
