const trailNear =(T,from)=>{
const G = grid();
let best = null,
bs = 1e9;
const dir = from ? new V3(from.x - T.x,0,from.z - T.z).normalize(): null;
if(G)
for(let j = -14;j <= 14;j++)
for(let i = -14;i <= 14;i++){
const d = Math.hypot(i,j);
if(d < 5 || d > 13)continue;
const[ci,cj]= cellOf(T.x + i,T.z + j);
if(!G.path[cj * GN + ci])continue;
let sc = Math.abs(d - 8);
if(dir)sc -=((i * dir.x + j * dir.z)/ d)* 2.5;
if(sc < bs){
bs = sc;
best = new V3(T.x + i,0,T.z + j);
}
}
if(!best){
const d2 = dir || new V3(1,0,0);
best = T.clone().addScaledVector(d2,8);
}
best.y = gy(best.x,best.z);
return best;
};
