if(spec === null)return;
const[tilt = 0,lean = 0,pv = 'c',dx = 0,dy = 0,hs = 1]= spec ||[];
const c = q.b.getCenter(new V3());
let px = c.x,
py = c.y;
if(pv === 'b')py = q.b.min.y;
else if(pv === 'l' && posts[0]){
px = posts[0].b.getCenter(v).x;
}else if(pv === 'r' && posts[1]){
px = posts[1].b.getCenter(v).x;
}
