'Bushes':{src:()=> BUSH,grp: o => o.name.slice(0,6),h: 0.85,tag: 'bush',sway: 0.06},
'Ferns':{src:()=> FERNG,grp: o => o.uuid,h: 0.6,tag: 'fern',sway: 0.06},
'Toadstools':{src:()=> MUSHG,grp: o => o.uuid,h: 0.2,tag: 'mush'},
'River stones':{src:()=> RIVR,grp: o => o.uuid,h: 0.4,stone: true},
'Leaf clumps':{src:()=> CLUMP,grp: o => o.uuid,h: 0.7,tag: 'clump',sway: 0.05},
'Rice':{src:()=> RICEG,grp:()=> 0,h: 0.5,tag: 'rice',sway: 0.06},
'Wheat':{src:()=> WHEATG,grp:()=> 0,h: 0.9,tag: 'wheat',sway: 0.08},
'Small pebbles':{src:()=> PEBG,grp:()=> 0,h: 0.12,stone: true}
