const packCache ={};
const packVars = name =>{
if(packCache[name])return packCache[name];
const D = PACKDEF[name];
if(D && D.grass){
packCache[name]=[];
return[];
}
const sc = D && D.src();
if(!sc){
packCache[name]=[];
return[];
}
const vs = kit(sc.scene,D.grp).filter(v => v.h > 1e-4);
try{
if(D.tag === 'bush')bushClump(vs);
else if(D.tag === 'flow')flowerDots(vs);
}catch(e){
console.warn('pack look',e);
}
if(D.stone)
vs.forEach((v,i)=>
v.parts.forEach((pt,pi)=>{
pt.g = paintRock(pt.g,1,i * 7 + pi + 40);
})
);
const colName = c =>{
if(!c)return '';
const h ={};
c.getHSL(h);
if(h.l > 0.8 || h.s < 0.12)return 'White';
const x = h.h;
return x < 0.03 || x > 0.95
? 'Red'
: x < 0.1
? 'Orange'
: x < 0.18
? 'Yellow'
: x < 0.45
? 'Green'
: x < 0.53
? 'Teal'
: x < 0.7
? 'Blue'
: x < 0.85
? 'Purple'
: 'Pink';
};
const hs = vs
.map(v => v.h)
.slice()
.sort((a,b)=> a - b);
const sizeOf = h =>{
const r = hs.indexOf(h)/ Math.max(1,hs.length - 1);
return r < 0.34 ? 'Small' : r < 0.67 ? 'Medium' : 'Large';
};
const used ={};
vs.forEach((v,i)=>{
let nm;
if(D.tag === 'flow'){
const pt = v.parts.find(p => p.mat && p.mat.color);
nm =(colName(pt && pt.mat.color)|| 'Mixed')+ ' flowers';
}else if(D.tag === 'bush')nm = sizeOf(v.h)+ ' bush';
else if(D.stone)nm = sizeOf(v.h)+ ' ' +(name === 'Small pebbles' ? 'pebble' : 'stone');
else nm = 'Variety';
used[nm]=(used[nm]|| 0)+ 1;
v.label = used[nm]> 1 ? nm + ' ' + used[nm]: nm;
});
vs.forEach((v,i)=>{
v.parts.forEach(pt =>{
pt.g.userData.src = pt.g.userData.src ||(sc.scene.children[0]&& 'pack:' + name);
pt.mat2 = D.stone
? stoneMat
: D.sway
? windMat(tintMat(pt.mat,(D.tag || 'pack')+ '_ed'),D.sway)
: tintMat(pt.mat,(D.tag || 'pack')+ '_ed');
});
});
packCache[name]= vs;
return vs;
};
const BATCH = new Map();
let batchDirty = new Set();
const bCell =
rec => Math.floor(rec.m[12]/ 28)+ ',' + Math.floor(rec.m[14]/ 28);
const bKey =(pack,v,pi,c)=> pack + '|' + v + '|' + pi + '|' + c;
const addRec = rec =>{
const vs = packVars(rec.pack);
const v = vs[rec.v];
if(!v)return;
const c =(rec.cell = bCell(rec));
v.parts.forEach((pt,pi)=>{
const k = bKey(rec.pack,rec.v,pi,c);
let b = BATCH.get(k);
if(!b){
b ={pack: rec.pack,v: rec.v,pi,recs:[],im: null};
BATCH.set(k,b);
}
b.recs.push(rec);
});
for(let pi = 0;pi < v.parts.length;pi++)batchDirty.add(bKey(rec.pack,rec.v,pi,c));
};
const dropRec = rec =>{
const v = packVars(rec.pack)[rec.v];
if(!v)return;
const c = rec.cell ?? bCell(rec);
v.parts.forEach((pt,pi)=>{
const k = bKey(rec.pack,rec.v,pi,c);
const b = BATCH.get(k);
if(b){
b.recs = b.recs.filter(r => r !== rec);
batchDirty.add(k);
}
});
};
const rebuildBatches =()=>{
const m = new THREE.Matrix4();
const pairs = new Map();
for(const k of batchDirty){
const b = BATCH.get(k);
if(!b)continue;
if(b.im){
scene.remove(b.im);
E.ims = E.ims.filter(x => x !== b.im);
b.im.dispose && b.im.dispose();
}
b.im = null;
if(!b.recs.length)continue;
const v = packVars(b.pack)[b.v];
const pt = v.parts[b.pi];
const im = new THREE.InstancedMesh(pt.g,pt.mat2,b.recs.length);
b.recs.forEach((r,i)=>{
m.fromArray(r.m);
im.setMatrixAt(i,m);
});
im.computeBoundingSphere();
im.castShadow = !!PACKDEF[b.pack].stone || b.pack === 'Bushes';
im.receiveShadow = true;
if(!PACKDEF[b.pack].stone)im.userData.cullD = 95;
im.userData.batch = b;
im.userData.edId = 'batch:' + k;
scene.add(im);
E.ims.push(im);
b.im = im;
const pk = b.pack + '|' + b.v;
if(!pairs.has(pk))pairs.set(pk,[]);
pairs.get(pk).push(im);
}
setTimeout(()=>{
try{
window.__seasonVis && window.__seasonVis();
}catch(e){}
},0);
for(const ims of pairs.values()){
const all =[];
const v = packVars(ims[0].userData.batch.pack);
for(const b of BATCH.values()){
if(b.im && b.pack === ims[0].userData.batch.pack && b.v === ims[0].userData.batch.v)all.push(b.im);
}
const ed ={partners: all};
for(const im of all)im.userData.ed = ed;
}
batchDirty.clear();
};
