const groundHit =(x,y)=>{
const r = renderer.domElement.getBoundingClientRect();
const v = new THREE.Vector2(((x - r.left)/ r.width)* 2 - 1,-((y - r.top)/ r.height)* 2 + 1);
ray.setFromCamera(v,camera);
const o = ray.ray.origin,
d = ray.ray.direction;
let prev = 0;
for(let t = 0.3;t < 220;t += 0.3){
const p = o.clone().addScaledVector(d,t);
if(p.y <= heightAt(p.x,p.z)){
let a = prev,
b = t;
for(let i = 0;i < 10;i++){
const mm =(a + b)/ 2;
const q = o.clone().addScaledVector(d,mm);
if(q.y <= heightAt(q.x,q.z))b = mm;
else a = mm;
}
const q = o.clone().addScaledVector(d,b);
q.y = heightAt(q.x,q.z);
return q;
}
prev = t;
}
return null;
};
const pickVar =()=>{
const vs = packVars($p('edPack').value);
const s = +$p('edVar').value;
return s >= 0 ? s :(Math.random()* vs.length)| 0;
};
const placeAt =(x,z)=>{
const pack = $p('edPack').value;
const vs = packVars(pack);
if(!vs.length)return null;
const vi = pickVar();
const v = vs[vi];
const D = PACKDEF[pack];
const sc =(D.h / v.h)* +$p('edSize').value *($p('edVary').checked ? 0.88 + Math.random()* 0.24 : 1);
const y = heightAt(x,z)-(D.stone ? sc * v.h * 0.15 : 0.02);
const m = new THREE.Matrix4().compose(
new V3(x,y,z),
new THREE.Quaternion().setFromEuler(new THREE.Euler(0,Math.random()* 6.283,0)),
new V3(sc,sc,sc)
);
return E.packRec(
pack,
vi,
m.toArray().map(n => +n.toFixed(4))
);
};
