const mc = grassU.uMask.value && grassU.uMask.value.image;
if(!mc || !mc.getContext)return;
const mx = mc.getContext('2d');
const W2P = mc.width / WORLD;
const X =(x + WORLD / 2)* W2P,
Z =(z + WORLD / 2)* W2P,
r = R * W2P;
const g = mx.createRadialGradient(X,Z,r * 0.35,X,Z,r);
const c = add ? '230,230,230' : '0,0,0';
g.addColorStop(0,`rgba(${c},${amt})`);
g.addColorStop(1,`rgba(${c},0)`);
